#!/bin/bash

# Experiment 3 (up): straight-line walking along X onto a rectangular platform
# (scenario of exp1 on the scene generated by Simulator/MJCF/generate_platform.py).

# ------------------------- experiment parameters -------------------------
ALGORITHM="vision"      # wbic | vision | dcm -> config/locomotion_controller.yaml
VEL_CMD_FRAME="local"   # local | global -> config/locomotion_controller.yaml

# Platform -> Simulator/MJCF/generate_platform.py [m]
PLATFORM_HEIGHT=0.15
PLATFORM_LENGTH=2.0
PLATFORM_WIDTH=2.0
PLATFORM_START_DIST=1.0

# Initial state -> config/simulation.yaml
INIT_BODY_POS="[0.0, 0.0, 0.4]"  # [x, y, z]
KIN_SCHEME="<<"                  # >> | << | >< | <> -> init_motor_angles

# ROS parameters of exp1 (must be float literals, e.g. 1.0, not 1)
BODY_Z=0.2
T_SW=0.28
T_ST=0.35
STRIDE_HEIGHT=0.06
REF_VELOCITY_X=0.3
WALK_TIME=15.0
RAMP_TIME=1.0

STARTUP_DELAY=5         # pause between run.sh start and exp1 start [s]
# -------------------------------------------------------------------------

set -euo pipefail

source "$(dirname -- "$0")/common.sh"

require_float PLATFORM_HEIGHT PLATFORM_LENGTH PLATFORM_WIDTH PLATFORM_START_DIST \
    BODY_Z T_SW T_ST STRIDE_HEIGHT REF_VELOCITY_X WALK_TIME RAMP_TIME
require_float_list INIT_BODY_POS

case "$KIN_SCHEME" in
    ">>") init_motor_angles="[0.0, 1.57, -3.14, -0.0, -1.57, 3.14, -0.0, 1.57, -3.14, 0.0, -1.57, 3.14]" ;;
    "<<") init_motor_angles="[0.0, -1.57, 3.14, -0.0, 1.57, -3.14, -0.0, -1.57, 3.14, 0.0, 1.57, -3.14]" ;;
    "><") init_motor_angles="[0.0, -1.57, 3.14, -0.0, 1.57, -3.14, -0.0, 1.57, -3.14, 0.0, -1.57, 3.14]" ;;
    "<>") init_motor_angles="[0.0, 1.57, -3.14, -0.0, -1.57, 3.14, -0.0, -1.57, 3.14, 0.0, 1.57, -3.14]" ;;
    *)
        echo "Unknown KIN_SCHEME: ${KIN_SCHEME} (supported: >>, <<, ><, <>)" >&2
        exit 1
        ;;
esac

python3 "${ROOT_DIR}/Simulator/MJCF/generate_platform.py" \
    --height "$PLATFORM_HEIGHT" \
    --length "$PLATFORM_LENGTH" \
    --width "$PLATFORM_WIDTH" \
    --start-dist "$PLATFORM_START_DIST"

setup_configs "$ALGORITHM" "$VEL_CMD_FRAME" platform
override_yaml_list "$sim_config" init_body_pos "$INIT_BODY_POS"
override_yaml_list "$sim_config" init_motor_angles "$init_motor_angles"

config_params+=(
    init_body_pos="$INIT_BODY_POS"
    kin_scheme="$KIN_SCHEME"
    init_motor_angles="$init_motor_angles"
    platform_height="$PLATFORM_HEIGHT"
    platform_length="$PLATFORM_LENGTH"
    platform_width="$PLATFORM_WIDTH"
    platform_start_dist="$PLATFORM_START_DIST"
)

ros_params=(
    body_z:="$BODY_Z"
    t_sw:="$T_SW"
    t_st:="$T_ST"
    stride_height:="$STRIDE_HEIGHT"
    ref_velocity_x:="$REF_VELOCITY_X"
    walk_time:="$WALK_TIME"
    ramp_time:="$RAMP_TIME"
)

# The scenario lasts 12.5 s + walk_time + ramp_time (phases of exp1_max_t_sw.py).
max_duration="$(awk -v w="$WALK_TIME" -v r="$RAMP_TIME" 'BEGIN { print 12.5 + w + r }')"

SCENARIO=exp1 run_experiment exp3_up \
    "${ALGORITHM}_${VEL_CMD_FRAME}_ph${PLATFORM_HEIGHT}_pl${PLATFORM_LENGTH}_pw${PLATFORM_WIDTH}_ps${PLATFORM_START_DIST}_z${BODY_Z}_tsw${T_SW}_tst${T_ST}_h${STRIDE_HEIGHT}_vx${REF_VELOCITY_X}_walk${WALK_TIME}_ramp${RAMP_TIME}" \
    "$max_duration" "${ros_params[@]}"
